modes.detail:
// ============ visited 数组是整个遍历的关键 ============
//
// 它记录"这个顶点去过没有"。两个地方都要用到：
//
//   ① **准备访问某个邻居之前**：去过就跳过，没去过才走
//   ② DFS 回溯的时候：标记保证不会重复回到走过的点
//
// 没有它会怎样？以那个正方形图为例，从 0 出发：
//
//   0 → 1 → 2 → 3 → 0 → 1 → 2 → 3 → 0 → ...
//
// 永远停不下来（实际会栈溢出或者死循环）。
//
// ============ 为什么用数组当队列/栈 ============
//
// 遍历时每个顶点**最多进一次**，所以容量最多就是顶点个数。
// 开一个 n 大小的数组，配两个下标就够了，比真的写一个栈/队列结构简单。
//
// 这也是一种常见做法：**当你能确定容量上界、又不需要复用的时候，
// 就地开个数组比引一个数据结构类更直接。**

// 最多多少个顶点
#define MAXV 100

// 邻接矩阵存图
typedef struct
{
// 顶点数
    int nv;
// 边数
    int ne;
// 矩阵：g[i][j] 非 0 表示 i 到 j 有边
    int g[MAXV][MAXV];
} MGraph;

// 状态码
#define OK 1
#define ERROR 0
typedef int Status;

// 用边表建图（和 04-01 一样）
// 无向图，一条边要填两个格子。
void CreateGraph(MGraph *G, int nv, const int edges[][2], int edgeCount)
{
// 循环用
    int i, j;

// 记规模
    G->nv = nv;
    G->ne = edgeCount;

// 矩阵清零
    for (i = 0; i < nv; i++)
    {
        for (j = 0; j < nv; j++)
        {
            G->g[i][j] = 0;
        }
    }

// 逐条边填两个方向
    for (i = 0; i < edgeCount; i++)
    {
        int u = edges[i][0];
        int v = edges[i][1];
        G->g[u][v] = 1;
        G->g[v][u] = 1;
    }
}

// 把 visited 数组清零，准备开始一次新的遍历
void ClearVisited(int visited[], int n)
{
// 循环清零
    int i;

    for (i = 0; i < n; i++)
    {
        visited[i] = 0;
    }
}

// 两数取大
int MaxInt2(int a, int b)
{
    return a > b ? a : b;
}

// 数一数图里有几条边（用来验证建图对不对）
int CountEdgesInMatrix(MGraph *G)
{
// 循环用
    int i, j;
// 计数：无向图每条边会被数到两次，所以最后要除以 2
    int count = 0;

    for (i = 0; i < G->nv; i++)
    {
        for (j = 0; j < G->nv; j++)
        {
            if (G->g[i][j] != 0)
            {
                count++;
            }
        }
    }

// 返回边数
    return count / 2;
}

