modes.detail:
// 递归版最好懂，但**递归深度受调用栈限制**。顶点一多可能栈溢出。
// 所以工程上常常改成显式的栈。

void DFSIter(MGraph *G, int v, int visited[])
{
// 栈：存"待访问的顶点"
    int stack[MAXV];
// 栈顶下标
    int top = -1;
// 当前处理的顶点
    int u;
// 循环用
    int i;

// 起点入栈
    stack[++top] = v;

// 栈不空就一直转
    while (top >= 0)
    {
// 弹出一个
        u = stack[top--];

// 如果已经访问过就跳过
// 为什么会有重复入栈？因为邻居是"入栈时就标记得还不够早"。
// 这里采用"出栈时才标记"的写法，所以要先判断。
        if (visited[u] != 0)
        {
            continue;
        }

// 标记并访问
        visited[u] = 1;
        printf("%d ", u);

// 把没去过的邻居都压进去
// 注意这里是**逆序**压栈（从大到小），因为栈是后进先出 ——
// 这样弹出的时候才是从小到大，和递归版的顺序一致。
        for (i = G->nv - 1; i >= 0; i--)
        {
            if (G->g[u][i] != 0 && visited[i] == 0)
            {
                stack[++top] = i;
            }
        }
    }
}

// 对比一下递归和迭代的顺序是否一致
int SameOrder(const int a[], const int b[], int n)
{
// 循环比较
    int i;

    for (i = 0; i < n; i++)
    {
        if (a[i] != b[i])
        {
            return 0;
        }
    }
    return 1;
}

