// ============ BFS 的走法 ============
//
// 还是那个正方形图，从 0 出发：
//
//          0 ── 1
//          │    │
//          3 ── 2
//
//   访问 0，把 0 入队
//   出队 0 → 它的邻居 1、3 都没去过 → 依次访问 1、3 并入队
//   出队 1 → 它的邻居 0（去过）、2（没去过）→ 访问 2 并入队
//   出队 3 → 邻居 0、2 都去过，什么都不做
//   出队 2 → 邻居都去过
//
//   结果：**0 1 3 2**
//
// 和 DFS 的 0 1 2 3 不同 —— BFS 是"一层一层"扩散的：
//
//   第 0 层：0
//   第 1 层：1、3     （0 的邻居）
//   第 2 层：2        （1 或 3 的邻居）
//
// ============ 为什么用队列 ============
//
// 因为 BFS 要求"先发现的先处理" —— 这正是队列（先进先出）的定义。
//
// 队列里存的顺序保证了：**同一层的点一定在同层的其他点之前被处理完**，
// 然后才轮到下一层。换成栈就变成 DFS 了。
//
// ============ 一个容易写错的细节 ============
//
// **入队的时候就要立刻标记 visited**，而不是出队的时候。
//
// 如果等到出队才标记，同一个顶点可能被它的多个邻居重复入队 ——
// 队列会膨胀，结果里也会出现重复。这个 bug 在小图上不明显，
// 图一大就暴露了。
//
// （上一模块的迭代版 DFS 用的是"出栈才标记"，那是可以的，
//   因为栈会去重；但队列不行，队列必须入队即标记。）

// 从顶点 v 出发做广度优先遍历
void BFS(MGraph *G, int v, int visited[])
{
// 队列：就地开一个数组
// 每个顶点最多入队一次，所以容量最多是顶点数。
    int queue[MAXV];
// 队头下标（出队处）
    int front = 0;
// 队尾下标（入队处）
    int rear = 0;
// 当前处理的顶点
    int u;
// 循环用
    int i;

// 起点：标记、访问、入队
// 标记和入队必须一起做，不能拖到出队时。
    visited[v] = 1;
    printf("%d ", v);
    queue[rear++] = v;

// 队列不空就一直转
    while (front < rear)
    {
// 出队一个
        u = queue[front++];

// 把它的所有没去过的邻居都访问掉并入队
        for (i = 0; i < G->nv; i++)
        {
            if (G->g[u][i] != 0 && visited[i] == 0)
            {
// 进队的同时立刻标记 —— 这里是关键
                visited[i] = 1;
// 访问
                printf("%d ", i);
// 入队，等轮到它时再去看它的邻居
                queue[rear++] = i;
            }
        }
    }
}

