// ============ 为什么外面还要套一层循环 ============
//
// 前面的 DFS、BFS 都只保证"从起点能到这个连通块的所有点"。
//
// 如果图是**非连通**的，比如：
//
//       0 ── 1        2 ── 3
//
// 从 0 出发只能走到 0 和 1，2 和 3 永远访问不到。
//
// 所以遍历整张图要写成：
//
//     for (每个顶点 v)
//         if (v 还没访问过)
//             DFS(G, v, visited);
//
// 外层这个循环每进入一次 DFS，就**多发现一个连通分量**。
// 所以这个循环还有一个副产品：**它转了几次，图就有几个连通分量**。
//
// ============ 这个模式在别处也出现 ============
//
// 求"连通分量个数"、判断"图是否连通"、找"孤立点"，都是这个写法。
// 记住它：**内层负责走完一个块，外层负责发现新的块。**

// 遍历整张图，返回连通分量的个数
// method 传 1 用 DFS，传 0 用 BFS（也就是用哪种方式都行）
int TraverseAll(MGraph *G, int visited[], int method)
{
// 循环用
    int i;
// 连通分量计数
    int components = 0;

// 清空标记，从头开始
    ClearVisited(visited, G->nv);

// 对每个顶点检查
    for (i = 0; i < G->nv; i++)
    {
// 没访问过 → 这是一个新连通分量的起点
        if (visited[i] == 0)
        {
// 分量数加一
            components++;
// 从它出发走完整个分量
            if (method == 1)
            {
                DFS(G, i, visited);
            }
            else
            {
                BFS(G, i, visited);
            }
        }
    }

// 返回分量个数
    return components;
}

