// 层次深一点的图
    CreateGraph(&G, 7, edges3, 6);
    printf("图三：0 连 1、2；1 连 3、4；2 连 5、6（一棵二叉树形状的图）\n");
    ClearVisited(visited, 7);
    printf("  DFS: ");
    DFS(&G, 0, visited);
    printf("\n");
    ClearVisited(visited, 7);
    printf("  BFS: ");
    BFS(&G, 0, visited);
    printf("\n");
    printf("  BFS 的序列是按「层」来的：0 → 1 2 → 3 4 5 6\n");
    printf("  DFS 则是一条路走到黑\n");
    printf("  （BFS 这个「按层输出」的性质，后面求最短路径会用到）\n");

// 正常结束
    return 0;
}

