#include <stdio.h>
#include <stdlib.h>


// 最多多少个顶点
#define MAXV 100

// 邻接矩阵存图
typedef struct
{
// 顶点数
    int nv;
// 边数
    int ne;
// 矩阵：g[i][j] 非 0 表示 i 到 j 有边
    int g[MAXV][MAXV];
} MGraph;

// 状态码
#define OK 1
#define ERROR 0
typedef int Status;

// 用边表建图（和 04-01 一样）
void CreateGraph(MGraph *G, int nv, const int edges[][2], int edgeCount)
{
// 循环用
    int i, j;

// 记规模
    G->nv = nv;
    G->ne = edgeCount;

// 矩阵清零
    for (i = 0; i < nv; i++)
    {
        for (j = 0; j < nv; j++)
        {
            G->g[i][j] = 0;
        }
    }

// 逐条边填两个方向
    for (i = 0; i < edgeCount; i++)
    {
        int u = edges[i][0];
        int v = edges[i][1];
        G->g[u][v] = 1;
        G->g[v][u] = 1;
    }
}

// 把 visited 数组清零，准备开始一次新的遍历
void ClearVisited(int visited[], int n)
{
// 循环清零
    int i;

    for (i = 0; i < n; i++)
    {
        visited[i] = 0;
    }
}

// 两数取大
int MaxInt2(int a, int b)
{
    return a > b ? a : b;
}

// 数一数图里有几条边（用来验证建图对不对）
int CountEdgesInMatrix(MGraph *G)
{
// 循环用
    int i, j;
// 计数：无向图每条边会被数到两次，所以最后要除以 2
    int count = 0;

    for (i = 0; i < G->nv; i++)
    {
        for (j = 0; j < G->nv; j++)
        {
            if (G->g[i][j] != 0)
            {
                count++;
            }
        }
    }

// 返回边数
    return count / 2;
}


// 从顶点 v 出发做深度优先遍历
void DFS(MGraph *G, int v, int visited[])
{
// 循环用
    int i;

// 标记自己已经访问
    visited[v] = 1;

// 访问（这里是打印）
    printf("%d ", v);

// 依次检查每个邻居
    for (i = 0; i < G->nv; i++)
    {
// 有边、且没去过 → 钻进去
        if (G->g[v][i] != 0 && visited[i] == 0)
        {
            DFS(G, i, visited);
        }
    }
// 循环结束后函数返回，这正是"回头"的动作
}


void DFSIter(MGraph *G, int v, int visited[])
{
// 栈：存"待访问的顶点"
    int stack[MAXV];
// 栈顶下标
    int top = -1;
// 当前处理的顶点
    int u;
// 循环用
    int i;

// 起点入栈
    stack[++top] = v;

// 栈不空就一直转
    while (top >= 0)
    {
// 弹出一个
        u = stack[top--];

// 如果已经访问过就跳过
        if (visited[u] != 0)
        {
            continue;
        }

// 标记并访问
        visited[u] = 1;
        printf("%d ", u);

// 把没去过的邻居都压进去
        for (i = G->nv - 1; i >= 0; i--)
        {
            if (G->g[u][i] != 0 && visited[i] == 0)
            {
                stack[++top] = i;
            }
        }
    }
}

// 对比一下递归和迭代的顺序是否一致
int SameOrder(const int a[], const int b[], int n)
{
// 循环比较
    int i;

    for (i = 0; i < n; i++)
    {
        if (a[i] != b[i])
        {
            return 0;
        }
    }
    return 1;
}


// 从顶点 v 出发做广度优先遍历
void BFS(MGraph *G, int v, int visited[])
{
// 队列：就地开一个数组
    int queue[MAXV];
// 队头下标（出队处）
    int front = 0;
// 队尾下标（入队处）
    int rear = 0;
// 当前处理的顶点
    int u;
// 循环用
    int i;

// 起点：标记、访问、入队
    visited[v] = 1;
    printf("%d ", v);
    queue[rear++] = v;

// 队列不空就一直转
    while (front < rear)
    {
// 出队一个
        u = queue[front++];

// 把它的所有没去过的邻居都访问掉并入队
        for (i = 0; i < G->nv; i++)
        {
            if (G->g[u][i] != 0 && visited[i] == 0)
            {
// 进队的同时立刻标记 —— 这里是关键
                visited[i] = 1;
// 访问
                printf("%d ", i);
// 入队，等轮到它时再去看它的邻居
                queue[rear++] = i;
            }
        }
    }
}


// 遍历整张图，返回连通分量的个数
int TraverseAll(MGraph *G, int visited[], int method)
{
// 循环用
    int i;
// 连通分量计数
    int components = 0;

// 清空标记，从头开始
    ClearVisited(visited, G->nv);

// 对每个顶点检查
    for (i = 0; i < G->nv; i++)
    {
// 没访问过 → 这是一个新连通分量的起点
        if (visited[i] == 0)
        {
// 分量数加一
            components++;
// 从它出发走完整个分量
            if (method == 1)
            {
                DFS(G, i, visited);
            }
            else
            {
                BFS(G, i, visited);
            }
        }
    }

// 返回分量个数
    return components;
}


// 主函数
int main(void)
{
// 正方形图：0-1，1-2，2-3，3-0
    static const int edges1[][2] = { { 0, 1 }, { 1, 2 }, { 2, 3 }, { 3, 0 } };
// 非连通图：0-1 和 2-3 两块
    static const int edges2[][2] = { { 0, 1 }, { 2, 3 } };
// 金字塔形（层次深，两种遍历差别明显）
    static const int edges3[][2] = { { 0, 1 }, { 0, 2 }, { 1, 3 }, { 1, 4 }, { 2, 5 }, { 2, 6 } };

// 图和标记数组
    MGraph G;
    int visited[MAXV];
// 连通分量数
    int comp;

// 建正方形图
    CreateGraph(&G, 4, edges1, 4);
    printf("图一：0-1，1-2，2-3，3-0（一个环）\n");
    printf("  矩阵里数出来的边数 = %d\n\n", CountEdgesInMatrix(&G));

// DFS
    ClearVisited(visited, 4);
    printf("  DFS 从 0 出发: ");
    DFS(&G, 0, visited);
    printf("\n");

// BFS
    ClearVisited(visited, 4);
    printf("  BFS 从 0 出发: ");
    BFS(&G, 0, visited);
    printf("\n");
    printf("  （DFS 一路钻到底，BFS 先看一圈邻居）\n\n");

// 从别的点出发试试
    ClearVisited(visited, 4);
    printf("  DFS 从 2 出发: ");
    DFS(&G, 2, visited);
    printf("\n");
    ClearVisited(visited, 4);
    printf("  BFS 从 2 出发: ");
    BFS(&G, 2, visited);
    printf("\n");
    printf("  （换个起点，序列跟着变 —— 但访问到的集合一样）\n\n");

// 对比递归版和迭代版 DFS
    ClearVisited(visited, 4);
    printf("  递归 DFS: ");
    DFS(&G, 0, visited);
    printf("\n");

    ClearVisited(visited, 4);
    printf("  栈版 DFS: ");
    DFSIter(&G, 0, visited);
    printf("\n");
    printf("  （两种写法结果一致 —— 逆序压栈就是为了对齐顺序）\n\n");

// 非连通图
    CreateGraph(&G, 4, edges2, 2);
    printf("图二：0-1 和 2-3（两块，不连通）\n");
    ClearVisited(visited, 4);
    printf("  只从 0 出发 DFS: ");
    DFS(&G, 0, visited);
    printf("   ← 只走到了 0 和 1，2、3 没碰到\n");

// 用 TraverseAll 遍历整张图
    comp = TraverseAll(&G, visited, 1);
    printf("\n  用 TraverseAll 遍历整张图: ");
    printf("（连通分量个数 = %d）\n", comp);
    printf("  （外层循环每进入一次 DFS，就发现一个新的连通分量）\n\n");

// 层次深一点的图
    CreateGraph(&G, 7, edges3, 6);
    printf("图三：0 连 1、2；1 连 3、4；2 连 5、6（一棵二叉树形状的图）\n");
    ClearVisited(visited, 7);
    printf("  DFS: ");
    DFS(&G, 0, visited);
    printf("\n");
    ClearVisited(visited, 7);
    printf("  BFS: ");
    BFS(&G, 0, visited);
    printf("\n");
    printf("  BFS 的序列是按「层」来的：0 → 1 2 → 3 4 5 6\n");
    printf("  DFS 则是一条路走到黑\n");
    printf("  （BFS 这个「按层输出」的性质，后面求最短路径会用到）\n");

// 正常结束
    return 0;
}

